package main
import("context";"encoding/json";"errors";"fmt";"os";"time";"github.com/google/uuid";"github.com/jackc/pgx/v5/pgxpool";"photoeditor/backend/internal/database";"photoeditor/backend/internal/objectstore";"photoeditor/backend/internal/upload")
type scopedLeases struct{upload.SQLCompletionLeases;allowed map[uuid.UUID]bool}
func(s scopedLeases)Claim(ctx context.Context)(*upload.CompletionLease,error){lease,err:=s.SQLCompletionLeases.Claim(ctx);if err!=nil||lease==nil{return lease,err};if !s.allowed[lease.UploadID]{_,_=s.SQLCompletionLeases.Release(ctx,*lease);return nil,errors.New("unexpected upload scope")};return lease,nil}
func run()error{ctx,cancel:=context.WithTimeout(context.Background(),5*time.Minute);defer cancel();var ids []uuid.UUID;if json.Unmarshal([]byte(os.Getenv("EXPECTED_UPLOAD_IDS")),&ids)!=nil||len(ids)!=15{return errors.New("expected fifteen explicitly scoped uploads")};allowed:=map[uuid.UUID]bool{};for _,id:=range ids{if id==uuid.Nil||allowed[id]{return errors.New("upload scope invalid")};allowed[id]=true};cfg,err:=pgxpool.ParseConfig(os.Getenv("DATABASE_URL"));if err!=nil{return errors.New("database config invalid")};cfg.MaxConns=2;cfg.ConnConfig.RuntimeParams["role"]="photo_scheduler";cfg.ConnConfig.RuntimeParams["statement_timeout"]="5000";cfg.ConnConfig.RuntimeParams["lock_timeout"]="3000";database.GuardApplicationRole(cfg);pool,err:=pgxpool.NewWithConfig(ctx,cfg);if err!=nil{return err};defer pool.Close();if err=database.RequireApplicationRole(ctx,pool,"photo_scheduler");err!=nil{return err};config:=objectstore.ConfigFromEnv(true);store,err:=objectstore.New(config);if err!=nil{return err};processor:=upload.CompletionProcessor{Leases:scopedLeases{upload.SQLCompletionLeases{DB:pool,Bucket:config.Bucket},allowed},Objects:store};completed:=0;for range ids{ok,err:=processor.ProcessOne(ctx);if err!=nil{return err};if !ok{return errors.New("completion did not commit")};completed++};fmt.Printf("{\"status\":\"ACTUAL_UPLOAD_COMPLETION_COMPONENT_PASS\",\"completed\":%d,\"scheduler_started\":false}\n",completed);return nil}
func main(){if err:=run();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)}}
